-- Reviewed administrative fees reuse the canonical ledger without publishing private source records.
-- Run after account workspace records, retail expenses, travel costs and home costs.
begin;
create table if not exists public.cb_legal_fee_links(id uuid not null unique default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,scope text not null check(scope in ('personal','demo')),project_ref text not null,record_ref text not null,shared_project uuid not null references public.cb_projects,expense_id uuid not null unique references public.cb_shared_expenses,source_hash text not null,revision bigint not null default 1,primary key(user_id,scope,project_ref,record_ref));
create table if not exists public.cb_legal_fee_writes(user_id uuid not null references auth.users on delete cascade,client uuid not null,payload jsonb not null,response jsonb not null,primary key(user_id,client));
create table if not exists public.cb_legal_fee_history(link_id uuid not null references public.cb_legal_fee_links(id),revision bigint not null,user_id uuid not null,snapshot jsonb not null,at timestamptz not null default now(),primary key(link_id,revision));
alter table public.cb_legal_fee_links enable row level security;alter table public.cb_legal_fee_writes enable row level security;alter table public.cb_legal_fee_history enable row level security;revoke all on public.cb_legal_fee_links,public.cb_legal_fee_writes,public.cb_legal_fee_history from public,anon,authenticated;
create or replace function public.cb_legal_fee_source(p_scope text,p_project text,p_ref text) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare p jsonb;r jsonb;shared uuid;begin
 if auth.uid() is null or p_scope is null or p_scope not in ('personal','demo') then raise exception 'Sign in to review your private fee' using errcode='42501';end if;
 select body->'value' into p from public.cb_workspace_records where user_id=auth.uid() and workspace='bride' and to_revision is null and body->>'kind'='item' and body->'value'->>'id'=p_project and (body->'path'=jsonb_build_array(p_scope,'projects') or p_scope='personal' and body->'path'=jsonb_build_array('projects')) order by jsonb_array_length(body->'path') desc limit 1;
 select body->'value' into r from public.cb_workspace_records where user_id=auth.uid() and workspace='bride' and to_revision is null and body->>'kind'='item' and body->'value'->>'id'=p_ref and (body->'path'=jsonb_build_array(p_scope,'legalRecords') or p_scope='personal' and body->'path'=jsonb_build_array('legalRecords')) order by jsonb_array_length(body->'path') desc limit 1;
 if p is null or r is null or r->>'projectId' is distinct from p_project or coalesce(r->>'kind','') not in ('Marriage registration','Identity & supporting documents','Appointments & witnesses','Name & account updates','International documentation') or coalesce((p->>'archived')::boolean,false) or coalesce(p->>'archiveStatus','') like 'Archived%' or coalesce((r->>'archived')::boolean,false) then raise exception 'Open your own active documentation record first' using errcode='42501';end if;
 if coalesce(p->>'sharedProjectId','')<>'' then if p->>'sharedProjectId'!~'^[a-fA-F0-9-]{36}$' then raise exception 'Review the wedding project connection';end if;shared=(p->>'sharedProjectId')::uuid;end if;
 return jsonb_build_object('shared',shared,'estimate',coalesce(r->'fee','0'::jsonb),'legacy_estimate',coalesce(r->>'expenseId','')<>'','source_hash',md5(jsonb_build_object('record',p_ref,'kind',r->>'kind','fee',r->'fee','project',shared)::text));end;$$;
create or replace function public.cb_private_legal_fee(p_scope text,p_project text,p_ref text,p_search text default '') returns jsonb language plpgsql stable security definer set search_path='' as $$
declare src jsonb;p uuid;l public.cb_legal_fee_links;available boolean;linked jsonb;begin
 src=public.cb_legal_fee_source(p_scope,p_project,p_ref);p=(src->>'shared')::uuid;available=p is not null and coalesce(public.cb_project_access(p,'read') and public.cb_project_access(p,'finance'),false);
 select * into l from public.cb_legal_fee_links where user_id=auth.uid() and scope=p_scope and project_ref=p_project and record_ref=p_ref;
 if p_search is null or length(p_search)>100 then raise exception 'Keep the expense search under 100 characters';end if;
 if not available or l.id is not null and l.shared_project is distinct from p then return src||jsonb_build_object('available',false,'can_link',false,'linked_elsewhere',l.id is not null and l.shared_project is distinct from p,'link',null,'choices','[]'::jsonb);end if;
 if l.id is not null then select to_jsonb(l)-'user_id'-'record_ref'-'project_ref'||jsonb_build_object('source_changed',l.source_hash<>src->>'source_hash','title',e.title,'currency',e.currency,'expense_revision',e.revision,'commitment',coalesce(e.settlement_total,e.agreed_total),'net_paid',coalesce((select sum(case when x.kind='Payment' then x.amount else -x.amount end) from public.cb_shared_payments x where x.expense_id=e.id),0),'balance',coalesce(e.settlement_total,e.agreed_total)-coalesce((select sum(case when x.kind='Payment' then x.amount else -x.amount end) from public.cb_shared_payments x where x.expense_id=e.id),0)) into linked from public.cb_shared_expenses e where e.id=l.expense_id and e.project_id=p;end if;
 return src||jsonb_build_object('available',true,'can_link',public.cb_project_access(p,'write'),'currency',coalesce((select currency from public.cb_project_finances where project_id=p),'USD'),'link',linked,'choices',(select coalesce(jsonb_agg(to_jsonb(e) order by e.title,e.id),'[]') from (select e.id,e.title,e.currency,coalesce(e.settlement_total,e.agreed_total) total,e.revision from public.cb_shared_expenses e where e.project_id=p and (p_search='' or e.title ilike '%'||p_search||'%') and not exists(select 1 from public.cb_home_cost_links where expense_id=e.id) and not exists(select 1 from public.cb_travel_cost_links where expense_id=e.id) and not exists(select 1 from public.cb_shopping_cost_links where expense_id=e.id) and not exists(select 1 from public.cb_legal_fee_links x where x.expense_id=e.id and (l.id is null or x.id<>l.id)) order by e.title,e.id limit 100) e));end;$$;
create or replace function public.cb_save_legal_fee(p_scope text,p_project text,p_ref text,p_shared uuid,p_source_hash text,p_link_revision bigint,p_client uuid,p_expense uuid,p_expense_revision bigint,p_data jsonb,p_confirm boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare src jsonb;l public.cb_legal_fee_links;e public.cb_shared_expenses;old public.cb_legal_fee_writes;payload jsonb;result jsonb;expense_data jsonb;link_id uuid;k text;begin
 -- Lock native project before private workspace, matching shared-project registration order.
 perform 1 from public.cb_projects where id=p_shared for update;perform 1 from public.cb_workspace_states where user_id=auth.uid() and workspace='bride' for update;
 src=public.cb_legal_fee_source(p_scope,p_project,p_ref);
 if (src->>'shared')::uuid is distinct from p_shared or p_shared is null or not coalesce(public.cb_project_access(p_shared,'read') and public.cb_project_access(p_shared,'write') and public.cb_project_access(p_shared,'finance'),false) then raise exception 'Current wedding planning and financial access required' using errcode='42501';end if;
 payload=jsonb_build_object('scope',p_scope,'project',p_project,'ref',p_ref,'shared',p_shared,'source',p_source_hash,'link_revision',p_link_revision,'expense',p_expense,'expense_revision',p_expense_revision,'data',p_data,'confirm',p_confirm);if p_client is null then raise exception 'Request ID required';end if;
 select * into old from public.cb_legal_fee_writes where user_id=auth.uid() and client=p_client;if found then if old.payload is distinct from payload then raise exception 'Retry the same reviewed fee connection' using errcode='PT409';end if;return old.response;end if;
 if p_confirm is distinct from true then raise exception 'Review and confirm which fee fields financial collaborators may see';end if;
 if src->>'source_hash' is distinct from p_source_hash then raise exception 'The private fee estimate or project changed. Reopen and review it first.' using errcode='PT409';end if;
 select * into l from public.cb_legal_fee_links where user_id=auth.uid() and scope=p_scope and project_ref=p_project and record_ref=p_ref for update;
 if l.id is not null and l.shared_project is distinct from p_shared then raise exception 'This fee is already linked to another wedding. Review its original ledger first.' using errcode='PT409';end if;
 if coalesce(l.revision,0) is distinct from p_link_revision then raise exception 'Another device updated this fee connection. Reopen to review.' using errcode='PT409';end if;
 link_id=coalesce(l.id,gen_random_uuid());
 if p_expense is null then
 if l.id is not null then raise exception 'This record already has a fee. Review the existing expense instead of creating another.' using errcode='PT409';end if;
 if p_expense_revision is not null or jsonb_typeof(p_data) is distinct from 'object' or p_data-array['title','supplier','currency','total']::text[]<>'{}' then raise exception 'Review the shared fee fields';end if;
 foreach k in array array['title','supplier','currency'] loop if jsonb_typeof(p_data->k) is distinct from 'string' then raise exception 'Review the fee text fields';end if;end loop;
 expense_data=jsonb_build_object('title',p_data->>'title','merchant',p_data->>'supplier','currency',p_data->>'currency','total',p_data->'total','quantity',1,'productUrl','','orderReference','','purchasedOn','','category','other','note','Reviewed administrative fee. Payments are recorded separately.');
 result=public.cb_create_retail_expense(p_shared,p_client,'admin-fee:'||link_id,null,null,expense_data,true);select * into e from public.cb_shared_expenses where id=(result->>'id')::uuid;
 else
 if p_data is not null then raise exception 'Select an existing expense without changing its financial fields';end if;
 select * into e from public.cb_shared_expenses where id=p_expense and project_id=p_shared for update;if e.id is null then raise exception 'Choose an expense from the current wedding' using errcode='42501';end if;
 if e.revision is distinct from p_expense_revision then raise exception 'This expense changed. Reopen and review it first.' using errcode='PT409';end if;
 if exists(select 1 from public.cb_home_cost_links where expense_id=e.id) or exists(select 1 from public.cb_travel_cost_links where expense_id=e.id) or exists(select 1 from public.cb_shopping_cost_links where expense_id=e.id) or exists(select 1 from public.cb_legal_fee_links where expense_id=e.id and id<>link_id) then raise exception 'This expense is already connected to another source. Choose its existing record instead.' using errcode='PT409';end if;end if;
 if l.id is not null and l.expense_id=e.id and l.source_hash=p_source_hash then result=to_jsonb(l)-'user_id';insert into public.cb_legal_fee_writes values(auth.uid(),p_client,payload,result);return result;end if;
 insert into public.cb_legal_fee_links(id,user_id,scope,project_ref,record_ref,shared_project,expense_id,source_hash) values(link_id,auth.uid(),p_scope,p_project,p_ref,p_shared,e.id,p_source_hash) on conflict(user_id,scope,project_ref,record_ref) do update set expense_id=excluded.expense_id,source_hash=excluded.source_hash,revision=cb_legal_fee_links.revision+1 returning * into l;
 result=to_jsonb(l)-'user_id';insert into public.cb_legal_fee_writes values(auth.uid(),p_client,payload,result);insert into public.cb_legal_fee_history values(l.id,l.revision,auth.uid(),result,now());return result;end;$$;
-- Preserve generic project activity and canonical presentation, including existing home/travel labels.
do $presentation$ declare body text;signature text;begin
 body=pg_get_functiondef('public.cb_create_retail_expense(uuid,uuid,text,uuid,bigint,jsonb,boolean)'::regprocedure);if strpos(body,'p_ref like ''admin-fee:%''')=0 then
 if strpos(body,'p_ref like ''home:%''')>0 then body=replace(body,'p_ref like ''home:%''','(p_ref like ''home:%'' or p_ref like ''admin-fee:%'')');else raise exception 'Install home-costs.sql before administrative fees';end if;execute body;end if;
 foreach signature in array array['public.cb_shared_ledger(uuid)','public.cb_shared_financial_report(uuid)','public.cb_support_allocations(uuid)'] loop body=pg_get_functiondef(to_regprocedure(signature));if strpos(body,'public.cb_legal_fee_links')=0 then body=replace(body,'coalesce(b.status,case when ','coalesce(b.status,case when e.retail_ref like ''personal:%:admin-fee:%'' or exists(select 1 from public.cb_legal_fee_links lf where lf.expense_id=e.id) then ''Administrative fee'' when ');if strpos(body,'public.cb_legal_fee_links')=0 then raise exception 'Financial presentation needs review: %',signature;end if;execute body;end if;end loop;
 foreach signature in array array['public.cb_save_home_cost(uuid,bigint,bigint,bigint,uuid,uuid,bigint,jsonb,boolean)','public.cb_save_travel_cost(uuid,bigint,bigint,bigint,uuid,uuid,bigint,jsonb,boolean)'] loop body=pg_get_functiondef(to_regprocedure(signature));if strpos(body,'public.cb_legal_fee_links')=0 then body=replace(body,' if e.revision is distinct from p_expense_revision then',' if exists(select 1 from public.cb_legal_fee_links where expense_id=e.id) then raise exception ''This expense is already connected to an administrative fee.'' using errcode=''PT409'';end if;'||chr(10)||' if e.revision is distinct from p_expense_revision then');if strpos(body,'public.cb_legal_fee_links')=0 then raise exception 'Expense allocation guard needs review';end if;execute body;end if;end loop;
end;$presentation$;
revoke all on function public.cb_legal_fee_source(text,text,text),public.cb_private_legal_fee(text,text,text,text),public.cb_save_legal_fee(text,text,text,uuid,text,bigint,uuid,uuid,bigint,jsonb,boolean) from public,anon,authenticated;
grant execute on function public.cb_private_legal_fee(text,text,text,text),public.cb_save_legal_fee(text,text,text,uuid,text,bigint,uuid,uuid,bigint,jsonb,boolean) to authenticated;
notify pgrst,'reload schema';commit;
